// ----- The databases' marks (filled, on a 24px grid) ---------------------------
// PostgreSQL's elephant is the mark from simple-icons (CC0); DynamoDB's is
// SpyDB's own drawing of AWS's stacked-disc mark.
function Mark({ children, ...props }: SVGProps<SVGSVGElement> & { children: ReactNode }) {
  return (
    <svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" {...props}>
      {children}
    </svg>
  )
}

